# Check for potential bugs more thoroughly
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# Check sieve for correctness up to n=1000
errors = []
for n in range(1, 100):
    result = list(sieve(n))
    expected_primes = [p for p in range(2, n) if all(p % d != 0 for d in range(2, int(p**0.5) + 1))]
    if result != expected_primes:
        errors.append(f"sieve({n}): got {result}, expected {expected_primes}")

if errors:
    print("SIEVE ERRORS:")
    for e in errors[:20]:
        print(e)
else:
    print("Sieve is correct for n=1..99")

# Check factor for correctness up to n=1000
from functools import reduce
import operator

errors = []
for n in range(1, 100):
    result = list(factor(n))
    if result:
        product = reduce(operator.mul, result, 1)
        if product != n:
            errors.append(f"factor({n}): product is {product}, expected {n}")

if errors:
    print("\nFACTOR ERRORS:")
    for e in errors[:20]:
        print(e)
else:
    print("Factor is correct for n=1..99")
